import { useState, useEffect } from "react";
import "./History.css";

const VERDICT_COLORS = {
  TRUE: "#22c55e",
  FALSE: "#ef4444",
  "PARTIALLY TRUE": "#f59e0b",
};

const VERDICT_ICONS = {
  TRUE: "✅",
  FALSE: "❌",
  "PARTIALLY TRUE": "⚠️",
};

export default function History() {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    try {
      const res = await fetch("http://localhost:8000/api/history");
      const data = await res.json();
      setHistory(data.history);
    } catch {
      setError("Could not load history. Make sure backend is running!");
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <div className="history-loading">Loading history...</div>;
  if (error) return <div className="history-error">{error}</div>;

  return (
    <div className="history">
      <div className="history-header">
        <h2>Check History</h2>
        <span className="history-count">{history.length} checks</span>
      </div>

      {history.length === 0 ? (
        <div className="history-empty">
          <span>📭</span>
          <p>No checks yet. Go check some text!</p>
        </div>
      ) : (
        <div className="history-list">
          {history.map((item) => (
            <div
              key={item.id}
              className="history-item"
              style={{ borderLeft: `4px solid ${VERDICT_COLORS[item.verdict]}` }}
            >
              <div className="history-item-header">
                <span className="history-verdict" style={{ color: VERDICT_COLORS[item.verdict] }}>
                  {VERDICT_ICONS[item.verdict]} {item.verdict}
                </span>
                <span className="history-confidence">{item.confidence}% confident</span>
                <span className="history-date">
                  {new Date(item.created_at).toLocaleDateString()}
                </span>
              </div>
              <p className="history-text">"{item.input_text.substring(0, 150)}..."</p>
              <p className="history-explanation">{item.explanation}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
